    let where = MARKS[0][LANG];
    MARKS.forEach((m, i) => { const on = t >= m.t - .004; markEls[i] && markEls[i].classList.toggle("on", on); if (on) where = m[LANG]; });
    whereEl.textContent = where;
    let cur = 0;
    steps.forEach((s, i) => { const on = p >= parseFloat(s.dataset.at); s.classList.toggle("on", on); if (on) cur = i; });
    steps.forEach((s, i) => s.classList.toggle("cur", i === cur));
