  // Chapitre I : citation qui s’éclaire et galerie horizontale
  scene($("#quote-rp"), p => { const n = Math.round(seg(p, .2, .62) * qWords.length); qWords.forEach((w, i) => w.classList.toggle("on", i < n)); }, "view");
  // Le magazine se feuillette page à page
