/* ---------- Apparitions ---------- */
if (!RM && "IntersectionObserver" in window) {
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); } }), { rootMargin: "0px 0px -12% 0px", threshold: .08 });
  $$(".rv").forEach(n => io.observe(n));
  // Compteurs
  const cio = new IntersectionObserver(es => es.forEach(e => {
    if (!e.isIntersecting) return;
    cio.unobserve(e.target);
    const b = e.target, target = parseFloat(b.dataset.count), dec = String(b.dataset.count).includes(".") ? 1 : 0, suf = b.dataset.suffix || "";
    const t0 = performance.now(), dur = 1800;
    const stepC = now => {
      const k = easeOut(clamp((now - t0) / dur));
      b.textContent = fmtCount(b, target * k);
      if (k < 1) requestAnimationFrame(stepC); else b.dataset.done = "1";
    };
    requestAnimationFrame(stepC);
  }), { threshold: .6 });
  $$("[data-count]").forEach(b => { b.textContent = fmtCount(b, 0); cio.observe(b); });
  // Vidéos d’ambiance : lecture muette quand elles sont visibles
  const vio = new IntersectionObserver(es => es.forEach(e => {
    const v = e.target;
    if (e.isIntersecting) { if (v.muted) { const pr = v.play(); if (pr && pr.catch) pr.catch(() => {}); } }
    else if (!v.paused) v.pause();
  }), { threshold: .45 });
  $$("video.auto").forEach(v => { v.muted = true; vio.observe(v); });
}
if (RM) $$("video.auto").forEach(v => { v.controls = true; });

/* ---------- Son des téléphones ---------- */
$$(".sound").forEach(b => b.addEventListener("click", () => {
  const v = b.closest(".body-ph").querySelector("video");
  const turnOn = v.muted;
  $$("#phones video").forEach(o => { if (o !== v) { o.muted = true; } });
  $$("#phones .sound").forEach(o => { if (o !== b) o.textContent = T("on"); });
  v.muted = !turnOn;
  if (turnOn) { v.currentTime = 0; const pr = v.play(); if (pr && pr.catch) pr.catch(() => {}); }
  b.textContent = turnOn ? T("off") : T("on");
}));

/* ---------- Filtres ---------- */
const rows = $$(".work");
