const lb = $("#lb");
let lbList = [], lbI = 0;
function showLb() {
  const k = lbList[lbI][0], c = cap(k) || lbList[lbI][1];
  const img = $("#lb-img"); img.src = SRC(k); img.alt = c || "";
  $("#lb-cap").textContent = (c ? c + " " : "") + (lbList.length > 1 ? "(" + (lbI + 1) + T("of") + lbList.length + ")" : "");
  $("#lb-prev").hidden = $("#lb-next").hidden = lbList.length < 2;
}
function openLb(list, i) { lbList = list; lbI = i; showLb(); lb.showModal(); $("#lb-close").focus(); }
const stepLb = d => { lbI = (lbI + d + lbList.length) % lbList.length; showLb(); };
