/* ---------- Langue ---------- */
function translateTree(root, map) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, { acceptNode: n => n.parentElement && !n.parentElement.closest("script,style,[data-i18n-skip]") ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT });
  const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n => { const raw = n.nodeValue, k = raw.trim(); if (k && map[k] !== undefined) n.nodeValue = raw.replace(k, map[k]); });
  $$("[alt],[aria-label]", root).forEach(e => {
    if (e.closest("[data-i18n-skip]")) return;
    ["alt", "aria-label"].forEach(a => { const v = e.getAttribute(a); if (v && map[v.trim()] !== undefined) e.setAttribute(a, map[v.trim()]); });
  });
}
function updateLangUI() {
  $$(".lang-btn").forEach(b => { b.textContent = T("btn"); b.setAttribute("aria-label", T("aria")); b.setAttribute("lang", T("other")); });
}
function setLang(l) {
  l = l === "en" ? "en" : "fr";
  if (l === LANG) { updateLangUI(); return; }
  const map = l === "en" ? I18N : I18N_REV;
  LANG = l;
  document.documentElement.lang = l;
  translateTree(document.body, map);
  $$("[data-en]").forEach(e => { e.textContent = l === "en" ? e.dataset.en : e.dataset.fr; });
  $$("[data-en-html]").forEach(e => { e.innerHTML = l === "en" ? e.dataset.enHtml : e.dataset.frHtml; });
  prepareSplits();
  buildChapters();
  H_reset();
  const bc = $("#book-cap"); if (bc) bc.dataset.init = "";
  $$("[data-count]").forEach(b => { if (b.dataset.done || RM) b.textContent = fmtCount(b, parseFloat(b.dataset.count)); });
  $$(".sound").forEach(b => { const v = b.closest(".body-ph").querySelector("video"); b.textContent = v && !v.muted ? T("off") : T("on"); });
  if (currentKind) applyFilter(currentKind);
  document.title = T("title");
  const md = $('meta[name="description"]'); if (md) md.setAttribute("content", T("desc"));
  updateLangUI();
  scenes.forEach(s => { s.last = -1; });
  request();
  if (dlg.open && current) openCase(current.id);
  if (lb.open) showLb();
  try { localStorage.setItem("olivia-lang", l); } catch (e) {}
}
$$(".lang-btn").forEach(b => b.addEventListener("click", () => setLang(LANG === "fr" ? "en" : "fr")));
(() => {
  let l = "fr";
  try { const q = new URLSearchParams(location.search).get("lang"); const s = localStorage.getItem("olivia-lang"); l = q || s || "fr"; } catch (e) {}
  if (l === "en") setLang("en"); else updateLangUI();
})();

